if = { limit = { any_country = { aor1776_hre_any_native_bond = yes } }
 set_global_variable = aor1776_hre_centralized_transfer_pending
}
else = { aor1776_hre_install_elected_country_legacy = yes }
}
aor1776_hre_finish_investiture = {

 if = { limit = { ruler ?= { is_character_alive = yes is_female = no age >= 18 NOT = { has_variable = aor1776_hre_deceased_emperor } } }
  ruler = { set_variable = aor1776_hre_emperor_character set_global_variable = { name = aor1776_hre_emperor_person value = this } }
 }
 else = { heir ?= { set_variable = aor1776_hre_emperor_character set_global_variable = { name = aor1776_hre_emperor_person value = this } } }
 if = { limit = { NOT = { this = global_var:aor1776_hre_emperor_country } }
  every_country = { limit = { has_diplomatic_pact = { who = global_var:aor1776_hre_emperor_country type = aor1776_imperial_obligation } } remove_diplomatic_pact = { country = global_var:aor1776_hre_emperor_country type = aor1776_imperial_obligation } }
 }
 set_global_variable = { name = aor1776_hre_emperor_country value = this }
 remove_global_variable = aor1776_hre_election_open
 remove_global_variable = aor1776_hre_election_deadlocked
 remove_global_variable = aor1776_hre_native_transfer_blocked
 remove_global_variable = aor1776_hre_runoff
 every_country = { remove_variable = aor1776_hre_finalist remove_variable = aor1776_hre_voter_this_round remove_variable = aor1776_hre_voted remove_variable = aor1776_hre_voted_for remove_variable = aor1776_hre_vote_deadline }
 remove_global_variable = aor1776_hre_election_pending
 aor1776_hre_refresh_pacts = yes


every_country = { limit = { has_variable = aor1776_hre_promise_cast } remove_variable = aor1776_hre_promised_candidate remove_variable = aor1776_hre_promise_cast }

aor1776_hre_feedback_refresh = yes

aor1776_hre_restore_membership = yes
aor1776_hre_schedule_membership_guard = yes

aor1776_hre_reform_controller = yes
}
aor1776_hre_defend_external_attack = {
if = { limit = { NOT = { has_variable = aor1776_hre_adjusting_backers } exists = global_var:aor1776_hre_emperor_country exists = scope:initiator exists = scope:target }
 set_variable = aor1776_hre_adjusting_backers
 global_var:aor1776_hre_emperor_country = { save_scope_as = hre_military_emperor }
 if = { limit = { scope:target = { aor1776_hre_member = yes } scope:initiator = { aor1776_hre_member = no }
  NOT = { scope:target = scope:hre_military_emperor } NOT = { has_variable = aor1776_hre_emperor_called_target }
  scope:hre_military_emperor.power_bloc ?= { has_principle_group = principle_group:aor1776_hre_group_circles } }
  set_variable = aor1776_hre_emperor_called_target
  if = { limit = { scope:hre_military_emperor = { NOT = { is_diplomatic_play_ally_of = scope:target } } } add_target_backers = { scope:hre_military_emperor } }
 }
 if = { limit = { scope:initiator = { aor1776_hre_member = yes } scope:target = { aor1776_hre_member = no }
  NOT = { scope:initiator = scope:hre_military_emperor } NOT = { has_variable = aor1776_hre_emperor_called_initiator }
  scope:hre_military_emperor.power_bloc ?= { OR = { has_principle = principle:aor1776_hre_circles_2 has_principle = principle:aor1776_hre_circles_3 } } }
  set_variable = aor1776_hre_emperor_called_initiator
  if = { limit = { scope:hre_military_emperor = { NOT = { is_diplomatic_play_ally_of = scope:initiator } } } add_initiator_backers = { scope:hre_military_emperor } }
 }
 if = { limit = { scope:initiator = { aor1776_hre_member = yes } scope:target = { aor1776_hre_member = yes }
  NOT = { scope:target = scope:hre_military_emperor } NOT = { scope:initiator = scope:hre_military_emperor }
  NOT = { has_variable = aor1776_hre_internal_neutrality_applied } }
  set_variable = aor1776_hre_internal_neutrality_applied
  if = { limit = { scope:hre_military_emperor = { is_diplomatic_play_ally_of = scope:initiator } } remove_initiator_backers = { scope:hre_military_emperor } }
  if = { limit = { scope:hre_military_emperor = { is_diplomatic_play_ally_of = scope:target } } remove_target_backers = { scope:hre_military_emperor } }
 }
if = { limit = { scope:initiator = scope:hre_military_emperor scope:target = { aor1776_hre_member = no }  OR = { scope:hre_military_emperor.power_bloc ?= { has_principle = principle:aor1776_hre_circles_3 } is_diplomatic_play_type = dp_aor1776_hre_restitution is_diplomatic_play_type = dp_aor1776_hre_subject_release }
    NOT = { has_variable = aor1776_hre_called_initiator_AUS } c:AUS ?= { aor1776_hre_member = yes NOT = { aor1776_hre_emperor = yes }
     NOT = { is_subject_of = scope:target } NOT = { top_overlord ?= scope:target } } }
    set_variable = aor1776_hre_called_initiator_AUS
    if = { limit = { c:AUS = { NOT = { is_diplomatic_play_ally_of = scope:initiator } NOT = { is_diplomatic_play_ally_of = scope:target } } } add_initiator_backers = { c:AUS } }
   }
if = { limit = { scope:target = scope:hre_military_emperor scope:initiator = { aor1776_hre_member = no } scope:hre_military_emperor.power_bloc ?= { has_principle = principle:aor1776_hre_circles_3 }
    NOT = { has_variable = aor1776_hre_called_target_AUS } c:AUS ?= { aor1776_hre_member = yes NOT = { aor1776_hre_emperor = yes }
     NOT = { is_subject_of = scope:initiator } NOT = { top_overlord ?= scope:initiator } } }
    set_variable = aor1776_hre_called_target_AUS
