								parentanchor = vcenter
								autoresize = yes
								align = nobaseline
								max_width = 450
								elide = right
								fontsize_min = 12
								text = "REQUEST_TO_JOIN"
							}
						}

						diplomatic_action_acceptance_icon = {
							parentanchor = vcenter|right
							position = { -10 0 }
						}
					}

