	}
}

# Triggered when a strait is partially reopened — Closed to NoMilitary, restoring economic access
catalyst_strait_partially_opened = {
	category = cc_relations_change

	political_lobby_creation = {
		lobby_pro_country = {
			value = 0.05

			if = {
				limit = { scope:target_country.country_rank > root.country_rank }
				multiply = 2
			}
		}
	}

	ai_country_goal_recalculation = {
		type = more_friendly
		chance = {
			value = 0.1
		}
	}
}

# Triggered when a strait is fully Closed — all affected countries lose access
catalyst_strait_closed = {
	category = cc_diplomatic_aggression

	political_lobby_creation = {
		lobby_anti_country = {
			value = 0.10

			if = {
				limit = { scope:target_country.country_rank > root.country_rank }
				multiply = 2
			}
		}
	}

	ai_country_goal_recalculation = {
		type = more_hostile
		chance = {
			value = 0.25
		}
	}
}

