		alpha = "[TransparentIfFalse( Not( And( Or( EqualTo_string( LensTab.GetKey, 'import_routes' ), EqualTo_string( LensTab.GetKey, 'export_routes' ) ), EqualTo_int32( LensOption.GetNumberOfSelections, '(int32)0' ) ) ) )]"

